import {activeLesson,learnerColor,canSelectLessonPiece,acceptsLessonMove,lessonGoalReached,chooseLessonReply,buildLessonDemo} from './lesson-rules.js';
import {checkedPosition} from './position-validation.js';
import {Chess} from './vendor/chess.js';
import {pieceSvg,pieceName,miniBoard} from './pieces.js';
import {themes,label,primaryTag,lessons,phaseCopy,difficulty} from './content.js';
import {progress,persist,recordAttempt,completePuzzle,completeLesson,markLessonLearned,bookmark,setLastPuzzle,dueIds,exportProgress,storageWarning} from './storage.js';
const main=document.querySelector('main'),nav=document.querySelector('#navigation');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString();
const button=(text,action,classes='',extra='')=>`<button class="button ${classes}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,href,classes='')=>`<a class="button ${classes}" href="${href}">${text}</a>`;
let data={puzzles:[],openings:[],manifest:{}},loaded=false,board=null,timer=null,toastTimer=null;
let filters={phase:'all',theme:'all',level:'all',query:'',page:0,saved:false};let openingFilter='';let openingLoad=null;let puzzleLoad=null;let searchTimer=null;const searchIndex=new Map();
const indices={puzzles:new Map(),openings:new Map()};
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3000)}
function saveNotice(){if(storageWarning())toast('Browser storage is unavailable. Export your progress to keep a backup.')}
function uciMove(game,uci){return game.move({from:uci.slice(0,2),to:uci.slice(2,4),promotion:uci[4]})}
function fullName(piece){return `${piece.color==='w'?'White':'Black'} ${pieceName[piece.type]}`}
function route(){const [page='home',query='']=location.hash.slice(1).split('?');return {page:page||'home',params:new URLSearchParams(query)}}
function go(page){if(location.hash===`#${page}`)render();else location.hash=page}
function cancelReply(){clearTimeout(timer);timer=null;if(board){board.busy=false;board.demoRunning=false}}
function shell(html){main.innerHTML=`<div class="shell">${html}</div>`}
function title(kicker,name,desc){return `<div class="page-title"><span class="eyebrow">${kicker}</span><h1>${name}</h1><p>${desc}</p></div>`}
function phaseName(p){return p==='opening'?'Openings':p==='endgame'?'Endgame':'Middlegame'}
function updateNav(page){document.body.classList.toggle('study-mode',['lesson','practice','opening','lab'].includes(page));nav.innerHTML=[['home','Home'],['learn','Learn'],['library','Library'],['openings','Openings'],['lab','Explore'],['progress','My progress']].map(([href,name])=>`<a href="#${href}" ${page===href||page==='lesson'&&href==='learn'||page==='practice'&&href==='library'?'class="active" aria-current="page"':''}>${name}</a>`).join('')}
function lessonCard(l){return `<a class="lesson-card" href="#lesson?id=${l.id}"><div class="card-visual">${miniBoard(l.fen)}</div><div class="card-body"><div class="card-meta"><span>${esc(l.phase)}</span><span>${progress.lessons[l.id]?'✓ Learned':progress.completedLessons[l.id]?'✓ Completed':l.time+' min'}</span></div><h3>${esc(l.name)}</h3><p>${esc(l.intro)}</p></div></a>`}
function puzzleCard(p){const tag=primaryTag(p);return `<a class="puzzle-card" href="#practice?id=${p.id}"><div class="card-visual">${miniBoard(p.fen)}</div><div class="card-body"><div class="card-meta"><span>${phaseName(p.phase)}</span><span>${progress.solved[p.id]?'✓ Solved':difficulty(p.rating)}</span></div><h3>${esc(label(tag))} <small>#${esc(p.id)}</small></h3><p>${p.fen.split(' ')[1]==='w'?'White':'Black'} to move · Puzzle rating ${p.rating}</p></div></a>`}
function phaseCount(phase){return data.manifest.counts?.[phase]||0}
function home(){board=null;const spotlight=data.puzzles.find(p=>p.themes.includes('fork')&&p.rating<1300)||data.manifest.spotlight;const nextLesson=lessons.find(l=>!progress.completedLessons[l.id]&&!progress.lessons[l.id])||lessons[0];main.innerHTML=`<section class="shell hero"><div><span class="sticker">SMALL MOVES. BIG AHA MOMENTS.</span><h1><span class="headline-line">Meet your next</span><span class="headline-line"><mark>chess obsession.</mark></span></h1><p class="lede">Find a pattern. Make your move. Get that “ohhh, I see it” feeling. From your first knight hop to your next brilliant finish.</p><div class="actions">${link((Object.keys(progress.lessons).length+Object.keys(progress.completedLessons).length)?'Continue learning ↗':'Start learning ↗',`#lesson?id=${nextLesson.id}`,'pink')}${link('Try beginner puzzles','#library?level=Starter','yellow')}</div><p class="footer-note">Real boards. Legal moves. A little more fun.</p></div><div class="hero-stage"><span class="floating-star" aria-hidden="true">✦</span><a class="hero-board" href="#practice?id=${spotlight.id}" style="display:block;color:inherit;text-decoration:none">${miniBoard(spotlight.fen)}<p class="hero-label">SPOT THE FORK. TRY THIS POSITION ↗</p></a><span class="hero-note">YOUR NEXT AHA MOMENT ↗</span></div></section><section class="stats-strip"><div class="stats-inner"><div class="stat"><b>${fmt(data.manifest.puzzles)}</b><span>real practice positions</span></div><div class="stat"><b>${fmt(data.manifest.openingLines)}</b><span>opening lines to explore</span></div><div class="stat"><b>${lessons.length}</b><span>guided starter lessons</span></div></div></section><section class="shell"><div class="section-heading"><div><span class="eyebrow">THE WHOLE GAME</span><h2>Three chapters.<br>Endless discoveries.</h2></div><p>Learn why the move works, then find the idea in a new position.</p></div><div class="track-grid">${[['opening','01','Open strong.','Bring your pieces into play, understand the plan, and spot early opportunities.','yellow','n'],['middlegame','02','Find your moment.','Forks, pins, sacrifices and quieter ideas. Learn to see what the board is telling you.','pink','q'],['endgame','03','Finish the story.','Turn small advantages into wins. Discover promotion, practical endings and defensive saves.','aqua','r']].map(([phase,num,name,copy,color,piece])=>`<a href="#library?phase=${phase}" class="track-card ${color}"><span class="track-number">${num} / ${phaseName(phase).toUpperCase()}</span><div class="track-icon">${pieceSvg({type:piece,color:'w'})}</div><h3>${name}</h3><p>${copy}</p><span class="plan-count">${fmt(phaseCount(phase))} positions</span><span class="arrow">↗</span></a>`).join('')}</div></section><section class="shell"><div class="section-heading"><div><span class="eyebrow">FIRST TIME HERE?</span><h2>The pieces have personalities.</h2></div>${link('See all starter lessons','#learn','small')}</div><div class="card-grid">${lessons.slice(0,4).map(lessonCard).join('')}</div></section><section class="section-band"><div class="shell"><span class="eyebrow">ONE IDEA. LOTS OF WAYS TO SEE IT.</span><h2>Don’t just memorize a move.<br>Learn to recognize the moment.</h2><p>Explore a visual atlas of motifs, practice them in real positions, and come back to the ones that need another look.</p><div class="actions">${link('Explore the pattern atlas','#atlas','pink')}${link('Open a free board','#lab','yellow')}</div></div></section><section class="shell"><div class="section-heading"><div><span class="eyebrow">THE LEARNING LOOP</span><h2>See it. Try it. Make it stick.</h2></div></div><div class="journey">${[['01','Get the idea','Start with a clear explanation and an exact board.'],['02','Play a move','Click or drag a piece. See its legal destinations.'],['03','Find the pattern','Practice with a real position and a graduated hint.'],['04','Come back smarter','Your solved puzzles return through spaced review.']].map(([n,h,p])=>`<div><b>${n}</b><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section>`}
function learn(){board=null;shell(title('THE STARTER PATH','Your first moves start here.','Learn how each piece moves, then connect rules to opening ideas, tactics and endgames.')+`<div class="notice">Watch one move, try the guided check, then solve a fresh position. Each board stops at its goal. Completed and learned are saved separately. Sign in to keep them across devices.</div><div class="section-heading" style="margin-top:28px"><h2>${Object.keys(progress.completedLessons).length} completed · ${Object.keys(progress.lessons).length} learned</h2>${link('Browse the pattern atlas','#atlas','small aqua')}</div>${[...new Set(lessons.map(l=>l.chapter))].map(ch=>`<h2 style="margin-top:32px">${esc(ch)}</h2><div class="card-grid">${lessons.filter(l=>l.chapter===ch).map(lessonCard).join('')}</div>`).join('')}`)}
function library(params){board=null;if(params.has('level'))filters.level=params.get('level');if(params.has('phase'))filters.phase=params.get('phase');if(params.has('theme'))filters.theme=params.get('theme');if(params.has('saved'))filters.saved=true;if(params.has('review'))filters.review=true;
 const themeOptions=Object.keys(themes).filter(t=>data.puzzles.some(p=>p.themes.includes(t)));
 shell(title('THE VISUAL LIBRARY','Find your next aha moment.',`${fmt(data.manifest.puzzles)} real practice positions. Search by motif, phase or opening name, then play the idea on the board.`)+`<div class="notice"><b>New to puzzles?</b> Start with a short set of mate-in-one positions. ${link('Try a beginner puzzle ↗','#practice?beginner=1','small pink')} ${link('Learn the pieces first','#learn','small')}</div><div class="filters">${[['all','All positions'],['opening','Openings'],['middlegame','Middlegame'],['endgame','Endgame']].map(([id,name])=>`<button class="filter ${filters.phase===id?'active':''}" data-action="phase" data-value="${id}">${name}</button>`).join('')}${link('Pattern atlas ↗','#atlas','small')}</div><div class="toolbar"><input type="search" id="library-search" aria-label="Search puzzle library" placeholder="Try fork, promotion, Italian…" value="${esc(filters.query)}"><label class="filter-label">Pattern <select id="theme-filter"><option value="all">Every pattern</option>${themeOptions.map(t=>`<option value="${t}" ${filters.theme===t?'selected':''}>${esc(label(t))}</option>`).join('')}</select></label><label class="filter-label">Difficulty <select id="level-filter">${['all','Starter','Building','Challenging','Advanced'].map(t=>`<option ${filters.level===t?'selected':''} value="${t}">${t==='all'?'Every level':t}</option>`).join('')}</select></label></div><div class="actions">${button(filters.saved?'✓ Saved only':'Saved only','saved-filter',filters.saved?'small aqua':'small')}${button(filters.review?'✓ Due for review':'Due for review','review-filter',filters.review?'small pink':'small')}${button('Clear filters','clear-filters','small')}</div><div id="library-results"></div>`);renderResults()}
function filtered(){const due=new Set(dueIds()),q=filters.query.toLowerCase().trim();return data.puzzles.filter(p=>(filters.phase==='all'||p.phase===filters.phase)&&(filters.theme==='all'||p.themes.includes(filters.theme))&&(filters.level==='all'||difficulty(p.rating)===filters.level)&&(!filters.saved||progress.bookmarks.includes(p.id))&&(!filters.review||due.has(p.id))&&(!q||searchIndex.get(p.id).includes(q))).sort((a,b)=>a.rating-b.rating)}
function renderResults(){const ps=filtered(),pages=Math.ceil(ps.length/24);filters.page=Math.max(0,Math.min(filters.page,pages-1));const shown=ps.slice(filters.page*24,(filters.page+1)*24);document.querySelector('#library-results').innerHTML=`<div class="result-meta"><span>${fmt(ps.length)} matching positions${ps.length?' · '+(filters.page*24+1)+'–'+Math.min((filters.page+1)*24,ps.length):''}</span><span>Unique boards · multiple tags may overlap</span></div>${shown.length?`<div class="card-grid">${shown.map(puzzleCard).join('')}</div><div class="pagination">${button('← Previous','previous-page','small',filters.page===0?'disabled':'')}<span>Page ${filters.page+1} of ${pages}</span>${button('Next →','next-page','small',filters.page+1>=pages?'disabled':'')}</div>`:`<div class="empty"><h2>No match this time.</h2><p>${filters.review?'No solved puzzles are due yet. Keep practicing; they’ll return when it’s time.':filters.saved?'Save a puzzle using the bookmark button on its lesson page.':'Try a different theme or clear your filters.'}</p>${button('Show all positions','clear-filters','yellow')}</div>`}`}
function atlas(){board=null;shell(title('THE PATTERN ATLAS','A name for that “I see it!” feeling.','Explore the ideas behind the moves. Every concept connects to real board positions and a focused practice set.')+`<div class="concept-grid">${Object.entries(themes).filter(([tag])=>data.puzzles.some(p=>p.themes.includes(tag))).map(([tag,t])=>`<a class="concept-card" href="#concept?tag=${tag}"><span class="eyebrow">${t.phase}</span><h3>${t.name}</h3><p>${t.text}</p><p style="margin-top:15px;font-weight:750">${fmt(data.puzzles.filter(p=>p.themes.includes(tag)).length)} examples ↗</p></a>`).join('')}</div>`)}
function conceptPage(tag){board=null;const t=themes[tag];if(!t){go('atlas');return}const examples=data.puzzles.filter(p=>p.themes.includes(tag)).sort((a,b)=>a.rating-b.rating);shell(`<a class="crumb" href="#atlas">← All patterns</a>`+title(t.phase,t.name,t.text)+`<div class="split-panel"><div class="panel"><h3>What to look for</h3><p>${t.cue}</p><h3>Easy trap to fall into</h3><p>${t.mistake}</p><div class="actions">${link('Practice this pattern ↗',`#practice?id=${examples[0].id}`,'pink')}${link('See every example',`#library?theme=${tag}`,'yellow')}</div></div><div class="home-preview"><a href="#practice?id=${examples[0].id}" aria-label="Try this ${esc(t.name)} example">${miniBoard(examples[0].fen)}</a><p class="board-caption">A real ${t.name.toLowerCase()} position · ${difficulty(examples[0].rating)} · ${examples[0].fen.split(' ')[1]==='w'?'White':'Black'} to move</p></div></div><div class="section-heading" style="margin-top:38px"><h2>See the idea in different positions.</h2></div><div class="card-grid">${examples.slice(0,8).map(puzzleCard).join('')}</div>`)}
function newBoard(kind,fen,extra={}){cancelReply();board={kind,game:checkedPosition(fen),initial:fen,selected:null,flipped:false,threats:false,legalHints:progress.settings.hints!==false,feedback:'',feedbackType:'',last:null,busy:false,...extra}}
function startPuzzle(id){const beginner=route().params.has('beginner');const p=indices.puzzles.get(id)||(beginner?data.puzzles.filter(p=>p.themes.includes('mateIn1')&&!progress.solved[p.id]).sort((a,b)=>a.rating-b.rating)[0]:null)||choosePuzzle();if(!p){go('library');return}setLastPuzzle(p.id);newBoard('puzzle',p.fen,{puzzle:p,ply:0,hintLevel:0,solved:false,revealed:false,mode:'practice',feedback:`${p.fen.split(' ')[1]==='w'?'White':'Black'} to move. Find the strongest continuation.`});board.flipped=p.fen.split(' ')[1]==='b';renderStudy()}
function choosePuzzle(){const due=dueIds().map(id=>indices.puzzles.get(id)).filter(Boolean);if(due.length)return due[0];if(progress.lastPuzzle&&!progress.solved[progress.lastPuzzle])return indices.puzzles.get(progress.lastPuzzle);const starter=data.puzzles.filter(p=>p.rating<1400&&!progress.solved[p.id]);return starter[Math.floor(Math.random()*starter.length)]||data.puzzles[Math.floor(Math.random()*data.puzzles.length)]}
function startLesson(id){const l=lessons.find(l=>l.id===id)||lessons[0];newBoard('lesson',l.fen,{lesson:l,step:'learn',demo:false,movedOrigins:[],feedback:'Watch the demonstration, then try one move yourself. Each exercise stops when its goal is met.'});renderStudy()}
function startOpening(id){const opening=indices.openings.get(id);newBoard('opening',new Chess().fen(),{opening:opening||null,replay:opening?.moves||[],replayIndex:0,feedback:'Click a move below or select a piece to explore any legal reply.'});renderStudy()}
function startLab(){newBoard('lab',new Chess().fen(),{feedback:'Explore freely. Both sides are yours to move; all legal destinations can be shown.'});renderStudy()}
function mobileTask(){const b=board;if(b.kind==='lesson')return b.step==='done'?'Lesson completed and saved. Continue to the next idea.':b.step==='guided-done'?'Practice complete. Try the fresh position next.':b.demoRunning?'Watch the move. The demonstration stops at its goal.':b.step==='test'?activeLesson(b).task:b.step==='practice'?b.lesson.task:b.lesson.intro;if(b.kind==='puzzle')return b.solved?'Puzzle solved!':b.revealed?'Study the solution below.':b.puzzle.themes.includes('mateIn1')?'Find checkmate in one move.':b.puzzle.themes.includes('mateIn2')?'Force checkmate in two of your moves.':'Find the strongest tactical continuation.';return 'Select a piece, then tap a legal destination.'}
function quickActions(){const b=board;if(b.kind==='lesson'){if(b.step==='learn')return button(b.demo?'Watch again':'Watch the move','lesson-demo','aqua')+button('Let me try ↗','lesson-practice','pink');if(b.step==='guided-done')return button('Try a fresh position ↗','lesson-test','pink');if(b.step==='done'){const next=lessons.slice(lessons.indexOf(b.lesson)+1).find(l=>!progress.completedLessons[l.id]&&!progress.lessons[l.id]);return next?link('Next lesson ↗','#lesson?id='+next.id,'pink'):link('Choose a lesson','#learn','pink')}return b.step==='practice'?button('Give me a hint','lesson-hint','small aqua'):''}if(b.kind==='puzzle'&&b.mode==='practice'&&!b.solved&&!b.revealed)return button('Hint','puzzle-hint','small aqua')+button('Show solution','puzzle-solution','small');if(b.kind==='puzzle'&&(b.solved||b.revealed))return button('Next position ↗','next-puzzle','pink')+button('Explore this board','puzzle-explore','small');return ''}
function boardHtml(){const g=board.game,files=board.flipped?'hgfedcba':'abcdefgh',ranks=board.flipped?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1];const moves=board.selected?g.moves({square:board.selected,verbose:true}):[],targets=new Set(moves.map(m=>m.to));let squares='';for(const rank of ranks)for(const file of files){const sq=file+rank,p=g.get(sq),dark=(file.charCodeAt(0)-97+rank)%2===0,legal=targets.has(sq)&&board.legalHints,threat=board.threats&&g.isAttacked(sq,g.turn()==='w'?'b':'w'),check=p?.type==='k'&&p.color===g.turn()&&g.isCheck();let classes='square'+(board.kind==='lesson'&&canSelectLessonPiece(board,sq)?' lesson-piece':'')+(dark?' dark':'')+(board.selected===sq?' selected':'')+(legal?' target':'')+(legal&&p?' capture-target':'')+(threat?' threatened':'')+(check?' checked':'')+(board.last?.from===sq||board.last?.to===sq?' last':'');squares+=`<button class="${classes}" data-square="${sq}" aria-label="${sq}${p?' '+fullName(p):' empty'}${legal?' legal destination':''}" aria-pressed="${board.selected===sq}" ${p?.color===g.turn()&&(board.kind!=='lesson'||canSelectLessonPiece(board,sq))?'draggable="true"':''} ${board.kind==='lesson'&&(board.busy||board.demo||!['practice','test'].includes(board.step)||p&&!canSelectLessonPiece(board,sq)&&!targets.has(sq))?'disabled':''}>${pieceSvg(p)}<span class="coordinate" aria-hidden="true">${sq}</span></button>`}const status=board.kind==='lesson'&&['done','guided-done'].includes(board.step)?'Goal reached · board paused':g.isCheckmate()?'Checkmate':g.isStalemate()?'Stalemate':g.isDraw()&&board.kind!=='lesson'?'Draw':g.isCheck()?'Check':`${g.turn()==='w'?'White':'Black'} to move`;return `<div class="mobile-task"><b>${board.kind==='lesson'?'Your lesson':board.kind==='puzzle'?'Your challenge':'On the board'}</b>${esc(mobileTask())}${board.feedbackType?'<p class="mobile-feedback">'+esc(board.feedback)+'</p>':''}<div class="actions">${quickActions()}</div></div><div class="board-info"><span><i class="turn-dot ${g.turn()==='b'?'black-dot':''}"></i>${status}${board.kind==='lesson'&&board.demo?' · demonstration':board.kind==='lesson'&&board.busy?' · watching':''}</span><span>${board.kind==='puzzle'?'#'+board.puzzle.id:board.kind==='opening'?'Opening explorer':board.kind==='lab'?'Free board':activeLesson(board).positionKind==='replayed-game'?'Legal game sequence':'Composed exercise'}</span></div><div class="board" id="chess-board" role="group" aria-label="Interactive chessboard" aria-busy="${board.busy}">${squares}</div><div class="board-controls">${button('↻ Reset','reset-board','small')}${button('⇅ Flip','flip-board','small')}${button('Legal moves','toggle-hints',board.legalHints?'small toggle':'small')}${button('Threats','toggle-threats',board.threats?'small toggle':'small')}${board.kind==='lab'||board.kind==='opening'||board.mode==='explore'?button('← Undo','undo-move','small',g.history().length?'':'disabled'):''}</div><p class="board-caption">${board.kind==='lesson'?board.lesson.selection==='any'?'Choose any White piece. The board stops when the goal is met. ':`Move a White ${pieceName[board.lesson.focus]}. The board stops when the goal is met. `:''}Click a piece, then a destination. You can also drag pieces or use Tab and Enter.${board.threats?' Pink outlines mark squares attacked by the other side.':''}</p>`}
function studyHeader(){if(board.kind==='lesson')return {back:'#learn',crumb:'Starter lessons',title:board.lesson.name,kicker:`${board.lesson.phase} · ${board.lesson.time} MIN`};if(board.kind==='puzzle')return {back:'#library',crumb:'Puzzle library',title:label(primaryTag(board.puzzle)),kicker:`${phaseName(board.puzzle.phase)} · ${difficulty(board.puzzle.rating)} · ${board.puzzle.rating}`};if(board.kind==='opening')return {back:'#openings',crumb:'Opening library',title:board.opening?.name||'Make your opening.',kicker:'OPENINGS · EXPLORE THE REPLIES'};return {back:'#home',crumb:'Home',title:'A board for your bright ideas.',kicker:'EXPLORE · EVERY LEGAL MOVE'}}
function renderStudy(focusSquare){if(!board)return;const hd=studyHeader();shell(`<a class="crumb" href="${hd.back}">← ${hd.crumb}</a><div class="study-title"><div><span class="eyebrow" style="margin-top:20px">${esc(hd.kicker)}</span><h1>${esc(hd.title)}</h1></div>${board.kind==='puzzle'?button(progress.bookmarks.includes(board.puzzle.id)?'★ Saved':'☆ Save','bookmark','small yellow'):''}</div><div class="workspace"><div class="board-shell" id="board-wrapper">${boardHtml()}</div><aside id="study-panel">${panelHtml()}</aside></div>`);if(focusSquare)document.querySelector(`[data-square="${focusSquare}"]`)?.focus({preventScroll:true});saveNotice()}
function feedbackHtml(){return `<div class="feedback ${board.feedbackType}" role="status" aria-live="polite">${esc(board.feedback||'Select a piece to get started.')}</div>`}
function moveFacts(){if(!board.last)return '';const m=board.last,g=board.game;let text=`${m.color==='w'?'White':'Black'} moves the ${pieceName[m.piece]} from ${m.from} to ${m.to}.`;if(m.captured)text+=m.flags.includes('e')?' It captures a pawn en passant.':` It captures a ${pieceName[m.captured]}.`;if(m.promotion)text+=` The pawn promotes to a ${pieceName[m.promotion]}.`;if(m.flags.includes('k')||m.flags.includes('q'))text+=' The rook moves automatically as part of castling.';if(g.isCheckmate())text+=' The king is in check and has no legal reply: checkmate.';else if(g.isCheck())text+=' The move gives check.';const attacked=[];for(const row of g.board())for(const p of row)if(p&&p.color!==m.color&&['q','r','b','n'].includes(p.type)&&g.attackers(p.square,m.color).includes(m.to))attacked.push(`${pieceName[p.type]} on ${p.square}`);if(attacked.length)text+=' The moved piece attacks '+attacked.join(' and ')+'.';return `<p class="move-explanation">${esc(text)}</p>`}
function moveList(){const moves=board.game.history({verbose:true});return `<div class="move-list" aria-label="Moves played">${moves.map((move,i)=>{const n=move.before.split(' ')[5];return `<span class="move-token ${i===moves.length-1?'current':''}">${n}${move.color==='w'?'.':'...'} ${esc(move.san)}</span>`}).join('')}</div>${moveFacts()}`}

function panelHtml(){const b=board;
 if(b.kind==='lesson'){
 const l=activeLesson(b),done=b.step==='done',guided=b.step==='guided-done',testing=b.step==='test';
 const next=lessons.slice(lessons.indexOf(b.lesson)+1).find(x=>!progress.completedLessons[x.id]&&!progress.lessons[x.id]);
 return `<div class="panel"><span class="eyebrow">${done?'COMPLETED':guided?'GUIDED PRACTICE COMPLETE':testing?'03 / FRESH POSITION':b.step==='practice'?'02 / GUIDED PRACTICE':'01 / WATCH & LEARN'}</span><h2>${done?'You did the thing.':guided?'Now make it stick.':testing?'Same idea. New board.':'One idea at a time.'}</h2><p>${esc(b.lesson.intro)}</p><p class="position-context">${l.positionKind==='replayed-game'?'Position reached from normal starting play.'+(l.setupMoves?.length?' Setup: '+esc(l.setupMoves.join(' · ')):''):'Composed exercise with a specific learning goal.'}</p><div class="concept-note"><b>${testing?'Fresh challenge':b.step==='practice'?'Your challenge':'Look for this'}</b><br>${esc(['practice','test'].includes(b.step)?l.task:b.lesson.cue)}</div>${feedbackHtml()}${moveList()}<div class="actions">${done?`${button('Practice again','lesson-practice','yellow')}${next?link('Next lesson ↗','#lesson?id='+next.id,'pink'):link('Explore the pattern atlas ↗','#atlas','pink')}`:guided?button('Try a fresh position ↗','lesson-test','pink'):b.step==='learn'?button(b.demo?'Watch again':'Watch the move','lesson-demo','aqua')+button('Let me try ↗','lesson-practice','pink'):button('Restart this check','lesson-restart','small')+(!testing?button('Give me a hint','lesson-hint','aqua'):'')}</div><div class="concept-note"><b>${progress.lessons[b.lesson.id]?'✓ Marked as learned':progress.completedLessons[b.lesson.id]?'✓ Completion saved automatically':'Your learning, your pace'}</b><p>${progress.lessons[b.lesson.id]?'You can revisit this idea whenever you like.':'Finish both practice checks for automatic completion, or mark it learned when you already know the idea.'}</p>${!progress.lessons[b.lesson.id]?button('Mark as learned','lesson-learned','small yellow',b.busy?'disabled':''):''}</div><h3>Watch out for…</h3><p class="muted">${esc(b.lesson.mistake)}</p></div>`;
 }
 if(b.kind==='puzzle'){const p=b.puzzle,tag=primaryTag(p),theme=themes[tag];const objective=p.themes.includes('mate')?'Find a forced checkmate.':p.themes.includes('equality')?'Find the continuation that saves the position.':'Find the strongest tactical continuation.';return `<div class="panel"><span class="eyebrow">${b.mode==='explore'?'EXPLORE WITHOUT SCORING':b.solved?'PATTERN SPOTTED':b.revealed?'SOLUTION STUDY':'YOUR MOVE'}</span><h2>${b.solved?'That’s the idea.':b.revealed?'See how it unfolds.':'What do you see?'}</h2><p>${objective}</p><div class="related-tags">${p.themes.filter(t=>themes[t]).slice(0,4).map(t=>`<a class="pill muted-pill" href="#concept?tag=${t}">${esc(label(t))}</a>`).join('')}</div>${feedbackHtml()}${moveList()}<div class="actions">${!b.solved&&!b.revealed&&b.mode==='practice'?button(`Hint${b.hintLevel?' ('+b.hintLevel+'/3)':''}`,'puzzle-hint','aqua')+button('Show solution','puzzle-solution','yellow'):''}${b.revealed?button('← Previous move','solution-prev','small',b.solutionIndex===0?'disabled':'')+button('Next move →','solution-next','small',b.solutionIndex>=p.moves.length?'disabled':''):''}${button('Next position ↗','next-puzzle','pink')}${button(b.mode==='explore'?'Back to challenge':'Explore this board','puzzle-explore','small')}</div><div class="concept-note"><b>${esc(label(tag))}</b><br>${esc(theme?.text||'Compare checks, captures and threats. Calculate the opponent’s reply before committing.')}</div><p class="muted" style="font-size:12px">${esc(theme?.cue||'Choose forcing candidate moves and follow the complete continuation.')}<br>Guidance explains the motif; the move sequence comes from the source puzzle.</p><a class="source-link" href="https://lichess.org/training/${p.id}" target="_blank" rel="noopener noreferrer">Source puzzle on Lichess ↗</a> · <a class="source-link" href="${esc(p.gameUrl)}" target="_blank" rel="noopener noreferrer">Original game ↗</a><p class="footer-note">Puzzle rating is the source’s difficulty estimate. Viewing a solution does not count as solving.</p></div>`}
 if(b.kind==='opening'){const history=b.game.history(),candidates=data.openings.filter(o=>history.every((m,i)=>o.moves[i]===m)),next=new Map();for(const o of candidates){const m=o.moves[history.length];if(m)next.set(m,(next.get(m)||0)+1)}const matches=data.openings.filter(o=>o.fen.split(' ').slice(0,4).join(' ')===b.game.fen().split(' ').slice(0,4).join(' '));return `<div class="panel"><span class="eyebrow">${b.opening?'NAMED LINE · '+b.opening.eco:'OPENING EXPLORER'}</span><h2>${b.opening?'Walk through the line.':'Choose a reply.'}</h2><p>Develop your pieces, influence the center and keep your king safe. Try a named move or select any piece to explore alternatives.</p>${feedbackHtml()}${moveList()}${b.opening?`<div class="actions">${button('← Previous','opening-prev','small',b.replayIndex===0?'disabled':'')}${button('Next move →','opening-next','pink',b.replayIndex>=b.replay.length?'disabled':'')}${button('Play whole line','opening-all','small aqua')}</div><p class="footer-note">${b.replayIndex} / ${b.replay.length} half-moves played</p>`:''}${matches.length?`<p class="notice" style="margin-top:20px">This position: ${esc(matches[0].name)}${matches.length>1?' · '+matches.length+' named transpositions':''}</p>`:''}<h3 style="margin-top:24px">Named continuations</h3><div class="opening-options">${[...next].sort((a,b)=>b[1]-a[1]).slice(0,12).map(([m,n])=>`<button class="opening-option" data-action="opening-move" data-value="${esc(m)}"><b>${esc(m)}</b><small>${fmt(n)} indexed lines ↗</small></button>`).join('')||'<p class="muted">No further named line in this library. You can still explore every legal move on the board.</p>'}</div><div class="concept-note">Opening popularity here means the number of indexed lines, not game frequency or an engine recommendation.</div>${button('Download PGN','download-pgn','small')}</div>`}
 return `<div class="panel"><span class="eyebrow">YOUR OWN CHESS SANDBOX</span><h2>What happens if…?</h2><p>Try any legal move, inspect threats, undo a decision or set up a position. You control both sides.</p>${feedbackHtml()}${moveList()}<label class="eyebrow" for="fen-input" style="margin-top:24px">LOAD A POSITION (FEN)</label><input id="fen-input" placeholder="Paste a full FEN position…" style="width:100%" aria-label="Position FEN"><div class="actions" style="margin-top:16px">${button('Load position','load-fen','yellow')}${button('Copy current FEN','copy-fen','small')}${button('Download PGN','download-pgn','small')}</div><div class="concept-note">Legal moves and attacked squares are rule-based. This board does not provide engine evaluation or play an opponent automatically.</div></div>`}
function statusFeedback(move){const g=board.game;return g.isCheckmate()?`${move.san}: checkmate. ${g.turn()==='w'?'Black':'White'} wins.`:g.isStalemate()?`${move.san}: stalemate. The side to move has no legal moves and is not in check.`:g.isDraw()?`${move.san}: this position is drawn.`:`${move.san} played. ${g.turn()==='w'?'White':'Black'} to move${g.isCheck()?' — the king is in check':''}.`}
function clickSquare(sq){if(!board||board.busy||board.solved&&board.mode==='practice'||board.revealed&&board.mode==='practice'||board.kind==='lesson'&&['done','guided-done'].includes(board.step))return;const p=board.game.get(sq);if(board.kind==='lesson'&&p?.color===learnerColor(board)&&!canSelectLessonPiece(board,sq))return;if(p?.color===board.game.turn()){board.selected=board.selected===sq?null:sq;renderStudy(sq);return}if(!board.selected){board.feedback=board.kind==='lesson'?`${board.lesson.selection==='any'?'Select a White piece.':'Select a highlighted White '+pieceName[board.lesson.focus]+'.'}`:'Select a piece belonging to the side whose turn it is.';board.feedbackType='';renderStudy(sq);return}requestMove(board.selected,sq)}
function requestMove(from,to){if(!board||board.busy||board.kind==='lesson'&&!canSelectLessonPiece(board,from))return;const candidates=board.game.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!candidates.length){board.feedback='That destination is not legal. Select a highlighted square; your king must stay safe.';board.feedbackType='error';renderStudy(to);return}if(candidates.some(m=>m.promotion)){const dialog=document.querySelector('#promotion'),options=document.querySelector('#promotion-options'),color=board.game.turn();options.innerHTML=['q','r','b','n'].map(t=>`<button type="button" data-promotion="${t}" aria-label="Promote to ${pieceName[t]}">${pieceSvg({type:t,color})}${pieceName[t]}</button>`).join('');board.pending={from,to};dialog.showModal();return}applyMove({from,to})}
function applyMove(input){if(!board||board.busy||(board.kind==='puzzle'&&board.mode==='practice'&&(board.solved||board.revealed))||(board.kind==='lesson'&&['done','guided-done'].includes(board.step)))return;if(board.kind==='lesson'&&!canSelectLessonPiece(board,input.from))return;let move;try{move=board.game.move(input)}catch{board.feedback='That move is not legal in this position.';board.feedbackType='error';renderStudy();return}board.selected=null;
 if(board.kind==='puzzle'&&board.mode==='practice'){const p=board.puzzle,uci=move.from+move.to+(move.promotion||''),expected=p.moves[board.ply],mateAlternate=p.themes.includes('mateIn1')&&board.game.isCheckmate();if(uci!==expected&&!mateAlternate){board.game.undo();board.feedback=`${move.san} is legal. This puzzle checks a different continuation; this alternative has not been evaluated here. Try a hint, or use Explore this board to follow your idea.`;board.feedbackType='error';recordAttempt(p.id,'retry',board.hintLevel);renderStudy(input.from);return}board.last=move;board.ply++;if(mateAlternate||board.ply>=p.moves.length){finishPuzzle();renderStudy(input.to);return}board.feedback=`Good find: ${move.san}. The opponent is replying…`;board.feedbackType='';board.busy=true;renderStudy(input.to);const current=board;timer=setTimeout(()=>{if(board!==current)return;board.last=uciMove(board.game,p.moves[board.ply]);board.ply++;board.busy=false;board.feedback=`The opponent played ${board.last.san}. Your turn — follow the idea.`;if(board.ply>=p.moves.length)finishPuzzle();renderStudy()},450);return}
 if(board.kind==='lesson'){
  const l=activeLesson(board);
  if(!acceptsLessonMove(board,move)){
   let consequence=board.game.isStalemate()?'That leaves Black without a legal move and without check: stalemate.':board.game.isCheckmate()?'That is checkmate, but this check asks for a different skill.':board.game.isCheck()?'That gives check.':move.captured?'That captures a '+pieceName[move.captured]+'.':'That moves your '+pieceName[move.piece]+' from '+move.from+' to '+move.to+'.';
   if(board.lesson.id==='development'&&['a3','h3'].includes(move.to))consequence='A knight on the edge has fewer destinations and less central influence than on c3 or f3.';
   board.game.undo();board.feedback=move.san+' is legal. '+consequence+' We put it back so you can compare. '+l.task;board.feedbackType='error';renderStudy(input.from);return;
  }
  board.last=move;board.selected=null;
  if(board.step==='test')finishLesson();else {board.step='guided-done';board.feedback=move.san+': '+l.why+' Goal reached — no extra move is needed.';board.feedbackType='success'}
  renderStudy(input.to);return;
 }

 board.last=move;board.feedback=statusFeedback(move);board.feedbackType=board.game.isCheckmate()?'success':'';if(board.kind==='opening'&&board.opening){const history=board.game.history();if(!history.every((m,i)=>board.replay[i]===m)){board.opening=null;board.replay=[];board.replayIndex=0;board.feedback+=' You’re exploring a different branch.'}else board.replayIndex=history.length}renderStudy(input.to)}
function finishPuzzle(){board.solved=true;board.feedback='Pattern spotted! You found the full continuation. This position is saved for a future review.';board.feedbackType='success';completePuzzle(board.puzzle.id,board.hintLevel);saveNotice()}
function resetBoard(){cancelReply();const b=board;b.game=new Chess(b.initial);b.selected=null;b.last=null;b.feedbackType='';if(b.kind==='puzzle'){b.ply=0;b.solved=false;b.revealed=false;b.hintLevel=0;b.feedback=b.mode==='explore'?'Explore freely; moves here are not scored.':'Start fresh. Find the strongest continuation.'}else if(b.kind==='opening'){b.replayIndex=0;b.feedback='Choose a move or step through the named line.'}else if(b.kind==='lesson'){b.initial=b.lesson.fen;b.game=new Chess(b.initial);b.testMode=false;b.step='learn';b.demo=false;b.movedOrigins=[];b.feedback='Watch the move, then try the practice checks.'}else b.feedback='A fresh board. What would you like to try?';renderStudy()}
function puzzleHint(){if(board.busy||board.solved||board.revealed)return;board.hintLevel=Math.min(3,board.hintLevel+1);const p=board.puzzle,move=p.moves[board.ply],piece=board.game.get(move.slice(0,2));if(board.hintLevel===1){const t=themes[primaryTag(p)];board.feedback='Pattern cue: '+(t?.cue||'Start with checks, captures and threats.')}else if(board.hintLevel===2){board.feedback=`Look at your ${pieceName[piece.type]} on ${move.slice(0,2)}.`;board.selected=move.slice(0,2)}else {board.feedback=`Try ${p.san[board.ply]}: ${move.slice(0,2)} → ${move.slice(2,4)}${move[4]?' (promote to '+pieceName[move[4]]+')':''}.`;board.selected=move.slice(0,2)}board.feedbackType='';renderStudy()}
function showSolution(){cancelReply();const p=board.puzzle;board.game=new Chess(p.fen);for(const m of p.moves)board.last=uciMove(board.game,m);board.selected=null;board.revealed=true;board.solved=false;board.ply=p.moves.length;board.solutionIndex=p.moves.length;board.feedback=`Solution: ${p.san.join(' · ')}. Reset the board to try it yourself; this view does not count as solved.`;board.feedbackType='';recordAttempt(p.id,'viewed',board.hintLevel);renderStudy()}
function solutionStep(delta){const b=board;if(!b?.revealed)return;b.solutionIndex=Math.max(0,Math.min(b.puzzle.moves.length,b.solutionIndex+delta));b.game=new Chess(b.initial);b.last=null;b.selected=null;for(const m of b.puzzle.moves.slice(0,b.solutionIndex))b.last=uciMove(b.game,m);b.feedback=b.solutionIndex?`Studying move ${b.solutionIndex} of ${b.puzzle.moves.length}: ${b.last.san}. This is solution study, not a scored attempt.`:'The learner’s starting position. Step forward to follow the solution.';renderStudy()}
function finishLesson(){board.step='done';completeLesson(board.lesson.id);board.feedback='Completed and saved! '+activeLesson({...board,step:'test'}).why;board.feedbackType='success';saveNotice()}
function showLessonDemo(){
 cancelReply();const current=board,line=buildLessonDemo(board.lesson);board.initial=board.lesson.fen;board.game=new Chess(board.initial);board.selected=null;board.last=null;board.demo=true;board.demoRunning=true;board.step='learn';board.testMode=false;board.busy=true;board.feedback='Watch the move. We stop as soon as the idea is shown.';board.feedbackType='';renderStudy();
 timer=setTimeout(()=>{if(board!==current||!board.demoRunning)return;board.last=uciMove(board.game,line[0]);board.busy=false;board.demoRunning=false;board.feedback=board.lesson.why+' Demonstration complete. Try it yourself next.';renderStudy()},500);
}
function lessonPractice(test=false){cancelReply();board.demo=false;board.testMode=test;const l=test?{...board.lesson,...board.lesson.transfer}:board.lesson;board.initial=l.fen;board.game=new Chess(board.initial);board.selected=null;board.last=null;board.step=test?'test':'practice';board.legalHints=!test;board.feedback=l.task+(test?' No hints for this check; use what you just learned.':'');board.feedbackType='';renderStudy()}
function openingStep(delta,all=false){const b=board;if(!b.opening)return;const target=all?b.replay.length:Math.max(0,Math.min(b.replay.length,b.replayIndex+delta));b.game=new Chess(b.initial);b.last=null;for(const move of b.replay.slice(0,target))b.last=b.game.move(move);b.replayIndex=target;b.selected=null;b.feedback=target===b.replay.length?'Named line complete. You can keep exploring the resulting position.':target?`Played ${b.last.san}. Keep developing and notice the changing central structure.`:'The starting position. Let’s see how this opening begins.';b.feedbackType='';renderStudy()}
function recommendedOpenings(){return `<section class="opening-start"><h2>Choose a first opening</h2><p>For White, develop with the Italian or Queen’s Gambit. For Black, explore a reply to e4 or d4. These are study suggestions, not engine rankings.</p><div class="card-grid">${[['Italian Game','White · e4','Develop toward the center and aim your bishop at f7.'],["Queen’s Gambit",'White · d4','Challenge the center with the c-pawn.'],['French Defense','Black · against e4','Prepare a central challenge with e6 and d5.'],["Queen’s Gambit Declined",'Black · against d4','Support d5 and develop behind the central pawns.']].map(([name,side,plan])=>{const normalized=name.replaceAll('’',"'");const o=data.openings.filter(o=>o.name===normalized||o.name.startsWith(normalized+':')).sort((a,b)=>a.moves.length-b.moves.length)[0];return o?`<a class="lesson-card" href="#opening?id=${o.id}"><div class="card-body"><span class="eyebrow">${side}</span><h3>${name}</h3><p>${plan}</p></div></a>`:''}).join('')}</div>${link('Learn opening principles first','#lesson?id=center','small yellow')}</section>`}
function openingLibrary(){board=null;shell(title('THE OPENING LIBRARY','Every opening starts with an idea.',`${fmt(data.manifest.openingLines)} named lines, from familiar beginnings to interesting sidelines. Step through a line or choose your own replies.`)+recommendedOpenings()+`<h2 style="margin-top:32px">Search every named line</h2><div class="notice">Opening names and moves are indexed from Lichess. Learn opening principles in the starter path; use this explorer to compare the resulting positions.</div><div class="toolbar"><input type="search" id="opening-search" placeholder="Search Italian, Sicilian, Queen’s Gambit, ECO…" aria-label="Search opening lines" value="${esc(openingFilter)}">${link('Explore from move one ↗','#opening','yellow')}</div><div id="opening-results"></div>`);openingResults()}
let openingPage=0;
function openingResults(){const q=openingFilter.toLowerCase(),all=data.openings.filter(o=>!q||(o.name+' '+o.eco).toLowerCase().includes(q)),pages=Math.ceil(all.length/24);openingPage=Math.max(0,Math.min(openingPage,pages-1));document.querySelector('#opening-results').innerHTML=`<div class="result-meta"><span>${fmt(all.length)} matching lines</span><span>Opening line counts differ from practice position counts</span></div><div class="card-grid">${all.slice(openingPage*24,(openingPage+1)*24).map(o=>`<a class="lesson-card" href="#opening?id=${o.id}"><div class="card-visual">${miniBoard(o.fen)}</div><div class="card-body"><div class="card-meta"><span>${o.eco}</span><span>${o.moves.length} half-moves</span></div><h3>${esc(o.name)}</h3><p>${esc(o.pgn)}</p></div></a>`).join('')}</div>${!all.length?'<div class="empty"><h2>No opening found.</h2><p>Try a family name or ECO code.</p></div>':`<div class="pagination">${button('← Previous','opening-page-prev','small',openingPage===0?'disabled':'')}<span>Page ${openingPage+1} of ${pages}</span>${button('Next →','opening-page-next','small',openingPage+1>=pages?'disabled':'')}</div>`}`}
function progressPage(){board=null;const solved=Object.keys(progress.solved).filter(id=>indices.puzzles.has(id)),learned=Object.keys(progress.lessons).length,due=dueIds().filter(id=>indices.puzzles.has(id));const recent=progress.attempts.filter(a=>a.outcome==='solved').slice(-8).reverse();shell(title('YOUR CHESS JOURNEY','Look at you, making moves.','A little practice adds up. Your lessons, saved positions and review dates stay in this browser.')+`<div class="notice"><b>Your next small step</b><p>Complete one lesson or practice three positions. Your progress stays in this browser.</p>${link('Continue learning ↗','#lesson?id='+(lessons.find(l=>!progress.completedLessons[l.id]&&!progress.lessons[l.id])||lessons[0]).id,'pink')}${due.length?link('Review '+due.length+' due positions','#library?review=1','small aqua'):link('Try beginner puzzles','#practice?beginner=1','small')}</div><div class="progress-numbers"><div><b>${solved.length}</b><span>distinct puzzles solved</span></div><div><b>${Object.keys(progress.completedLessons).length}/${lessons.length}</b><span>lessons completed · ${learned} self-marked as learned</span></div><div><b>${due.length}</b><span>positions due for review</span></div></div><div class="actions">${link('Practice a position ↗','#practice','pink')}${link('My saved positions', '#library?saved=1','yellow')}${due.length?link('Review due positions','#library?review=1','aqua'):''}${button('Export my progress','export-progress','small')}</div><div class="split-panel" style="margin-top:30px"><section class="panel"><h2>Practice by phase</h2>${['opening','middlegame','endgame'].map(phase=>{const count=solved.filter(id=>indices.puzzles.get(id).phase===phase).length,total=phaseCount(phase);return `<div class="progress-row"><b>${phaseName(phase)}</b><div class="progress-bar" aria-label="${count} of ${total} ${phase} puzzles solved"><span style="width:${count/total*100}%"></span></div><span>${count}</span></div>`}).join('')}<p class="footer-note">Counts show completed positions, not a chess rating or calibrated mastery score.</p></section><section class="panel"><h2>${recent.length?'Your recent aha moments':'Your story starts here.'}</h2>${recent.length?`<table class="history-table"><tbody>${recent.map(a=>{const p=indices.puzzles.get(a.id);return p?`<tr><td><a href="#practice?id=${p.id}">${esc(label(primaryTag(p)))} · #${p.id}</a></td><td>${new Date(a.at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</td></tr>`:''}).join('')}</tbody></table>`:`<p>Try a starter lesson or solve your first puzzle. We’ll keep your place as you go.</p>${link('Meet the knight','#lesson?id=knight','yellow')}`}</section></div><p class="footer-note">Review intervals increase after successful practice. Hinted solutions return sooner. Browser storage is local to this device and website address; there is no sign-in or cross-device sync.</p>`)}
function about(){board=null;shell(title('BEHIND THE BOARD','Real positions. Clear provenance.','A growing chess learning app built around exact diagrams, legal movement and original instruction.')+`<div class="split-panel"><div class="panel"><h2>What’s in this version</h2><ul class="tip-list"><li>${fmt(data.manifest.puzzles)} distinct puzzles with complete legal move replay checks.</li><li>${fmt(data.manifest.openingLines)} named opening lines.</li><li>${lessons.length} original guided lessons, a pattern atlas and a free board.</li><li>Hints, solution study, bookmarks and browser-local learning progress.</li></ul><p>Puzzle moves, ratings and theme tags come from the <a href="https://database.lichess.org/" target="_blank" rel="noopener noreferrer">Lichess CC0 database</a>. Opening names come from the <a href="https://github.com/lichess-org/chess-openings" target="_blank" rel="noopener noreferrer">CC0 opening dataset</a>. Board rules use <a href="./vendor/chess-LICENSE.txt">chess.js (BSD-2-Clause)</a>.</p></div><div class="panel"><h2>How learning is checked</h2><p>The importer applies the source opponent’s move before presenting each puzzle. It checks each starting position for correct side to move, king safety, pawn placement, castling and en passant state; then verifies every solution move is legal and that tagged mate sequences end in mate. Duplicate board states are removed. Basic movement lessons are reached by replaying legal moves from the normal starting board. Reduced endgame studies are labeled as composed exercises.</p><p>Puzzle solutions are source-provided, not independently reanalyzed by an engine here. The pattern text is original concept guidance; it does not claim to be a coach’s annotation of every position.</p><p>Promotion offers all four choices. Any legal mate-in-one answer counts. Opening exploration and the free board are unscored.</p><p>Import: ${new Date(data.manifest.importedAt).toLocaleDateString()} · ${fmt(data.manifest.scanned)} source rows inspected.</p></div></div>`)}
function download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function render(){if(!loaded)return;cancelReply();const {page,params}=route();updateNav(page);if(['library','practice','atlas','concept','progress'].includes(page)&&!data.puzzles.length){loadPuzzleLibrary();return}if((page==='openings'||page==='opening')&&!data.openings.length){loadOpeningLibrary();return}switch(page){case 'home':home();break;case 'learn':learn();break;case 'library':library(params);break;case 'atlas':atlas();break;case 'concept':conceptPage(params.get('tag'));break;case 'lesson':startLesson(params.get('id'));break;case 'practice':startPuzzle(params.get('id'));break;case 'openings':openingLibrary();break;case 'opening':startOpening(params.get('id'));break;case 'lab':startLab();break;case 'progress':progressPage();break;case 'about':about();break;default:home()}document.title=page==='home'?'Sahar Chess — your next chess obsession':`Sahar Chess — ${page==='practice'?'Practice':page[0]?.toUpperCase()+page.slice(1)}`}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){filters.query=e.target.value;filters.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(document.querySelector('#library-results'))renderResults()},120)}if(e.target.id==='opening-search'){openingFilter=e.target.value;openingPage=0;openingResults()}});
document.addEventListener('change',e=>{if(e.target.id==='theme-filter'){filters.theme=e.target.value;filters.page=0;renderResults()}if(e.target.id==='level-filter'){filters.level=e.target.value;filters.page=0;renderResults()}});
let dragFrom=null;
document.addEventListener('dragstart',e=>{const square=e.target.closest('[data-square]');if(!square||!board||board.busy||board.kind==='lesson'&&!canSelectLessonPiece(board,square.dataset.square)){e.preventDefault();return}e.dataTransfer.setData('text/plain',square.dataset.square);dragFrom=square.dataset.square});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-square]'))e.preventDefault()});
document.addEventListener('drop',e=>{const square=e.target.closest('[data-square]');if(!square||!board)return;e.preventDefault();const from=e.dataTransfer.getData('text/plain');if(from&&dragFrom===from)requestMove(from,square.dataset.square);dragFrom=null});
document.addEventListener('dragend',()=>dragFrom=null);
document.querySelector('#promotion').addEventListener('close',()=>{if(board)board.pending=null});
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();main.focus();main.scrollIntoView();return}const promoted=e.target.closest('[data-promotion]');if(promoted&&board?.pending){const {from,to}=board.pending,promotion=promoted.dataset.promotion;document.querySelector('#promotion').close();applyMove({from,to,promotion});return}const square=e.target.closest('[data-square]');if(square){clickSquare(square.dataset.square);return}const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,value=target.dataset.value;
 switch(action){
 case 'phase':filters.phase=value;filters.page=0;document.querySelectorAll('[data-action=phase]').forEach(el=>el.classList.toggle('active',el.dataset.value===value));renderResults();break;
 case 'saved-filter':filters.saved=!filters.saved;filters.page=0;library(new URLSearchParams());break;
 case 'review-filter':filters.review=!filters.review;filters.page=0;library(new URLSearchParams());break;
 case 'clear-filters':filters={phase:'all',theme:'all',level:'all',query:'',page:0,saved:false,review:false};history.replaceState(null,'','#library');library(new URLSearchParams());break;
 case 'previous-page':filters.page--;renderResults();document.querySelector('#library-results').scrollIntoView();break;
 case 'next-page':filters.page++;renderResults();document.querySelector('#library-results').scrollIntoView();break;
 case 'opening-page-prev':openingPage--;openingResults();document.querySelector('#opening-results').scrollIntoView();break;
 case 'opening-page-next':openingPage++;openingResults();document.querySelector('#opening-results').scrollIntoView();break;
 case 'reset-board':resetBoard();break;
 case 'flip-board':board.flipped=!board.flipped;renderStudy();break;
 case 'toggle-hints':board.legalHints=!board.legalHints;progress.settings.hints=board.legalHints;persist();renderStudy();break;
 case 'toggle-threats':board.threats=!board.threats;renderStudy();break;
 case 'undo-move':{const move=board.game.undo();if(move){board.selected=null;board.last=board.game.history({verbose:true}).at(-1)||null;board.feedback='Undid '+move.san+'. Try a different idea.';board.feedbackType='';if(board.kind==='opening')board.replayIndex=board.game.history().length;renderStudy()}break}
 case 'bookmark':{const saved=bookmark(board.puzzle.id);toast(saved?'Saved for another look.':'Removed from saved positions.');renderStudy();break}
 case 'puzzle-hint':puzzleHint();break;
 case 'puzzle-solution':showSolution();break;
 case 'solution-prev':solutionStep(-1);break;
 case 'solution-next':solutionStep(1);break;
 case 'next-puzzle':{if(route().params.has('beginner')){const next=data.puzzles.filter(p=>p.id!==board.puzzle.id&&p.themes.includes('mateIn1')&&!progress.solved[p.id]).sort((a,b)=>a.rating-b.rating)[0];if(next){go('practice?id='+next.id+'&beginner=1');break}}const tag=primaryTag(board.puzzle),candidates=data.puzzles.filter(p=>p.id!==board.puzzle.id&&p.themes.includes(tag)&&!progress.solved[p.id]);const next=candidates[Math.floor(Math.random()*candidates.length)]||data.puzzles[(data.puzzles.indexOf(board.puzzle)+1)%data.puzzles.length];go(`practice?id=${next.id}`);break}
 case 'puzzle-explore':{cancelReply();board.mode=board.mode==='practice'?'explore':'practice';board.game=new Chess(board.initial);board.ply=0;board.solved=false;board.revealed=false;board.selected=null;board.last=null;board.feedback=board.mode==='explore'?'Explore any legal continuation. These moves do not count toward solving.':'Challenge reset. Find the source continuation.';board.feedbackType='';renderStudy();break}
 case 'lesson-demo':showLessonDemo();break;
 case 'lesson-practice':lessonPractice();break;
 case 'lesson-test':lessonPractice(true);break;
 case 'lesson-restart':lessonPractice(board.step==='test');break;
 case 'lesson-learned':markLessonLearned(board.lesson.id);toast('Marked as learned.');renderStudy();break;
 case 'lesson-hint':if(board.busy)return;board.selected=board.lesson.move.slice(0,2);board.feedback=board.lesson.task+' '+board.lesson.cue;board.feedbackType='';renderStudy();break;
 case 'opening-prev':openingStep(-1);break;
 case 'opening-next':openingStep(1);break;
 case 'opening-all':openingStep(0,true);break;
 case 'opening-move':{let move;try{move=board.game.moves({verbose:true}).find(m=>m.san===value);if(move)applyMove({from:move.from,to:move.to,promotion:move.promotion})}catch{toast('That opening move is unavailable.')}break}
 case 'load-fen':{const fen=document.querySelector('#fen-input').value.trim();try{const game=checkedPosition(fen);board.game=game;board.initial=game.fen();board.last=null;board.selected=null;board.feedback='Position loaded. '+(game.turn()==='w'?'White':'Black')+' to move.';board.feedbackType='';renderStudy()}catch{board.feedback='That position is invalid. Check whose turn it is, king safety, pawn placement, castling rights and en passant.';board.feedbackType='error';document.querySelector('#study-panel').innerHTML=panelHtml()}break}
 case 'copy-fen':try{await navigator.clipboard.writeText(board.game.fen());toast('Position copied.')}catch{toast('Clipboard unavailable. Download the PGN instead.')}break;
 case 'download-pgn':download(board.game.pgn()||'[Event "Sahar Chess"]\n[SetUp "1"]\n[FEN "'+board.game.fen()+'"]\n','sahar-chess-study.pgn');break;
 case 'export-progress':download(exportProgress(),'sahar-chess-progress.json','application/json');toast('Progress backup downloaded.');break;
 case 'retry-load':boot();break;
 case 'retry-openings':loadOpeningLibrary();break;
 case 'retry-puzzles':loadPuzzleLibrary();break;
 }
});
async function loadOpeningLibrary(){
 shell('<div class="loading"><span class="star">✦</span><h1>Opening the opening library…</h1><p>Bringing the named lines to your board.</p></div>');
 try{if(!openingLoad)openingLoad=fetch('./data/openings.json').then(r=>{if(!r.ok)throw new Error('Opening library unavailable');return r.json()});data.openings=await openingLoad;indices.openings.clear();for(const o of data.openings)indices.openings.set(o.id,o);if(['openings','opening'].includes(route().page))render()}catch{openingLoad=null;if(['opening','openings'].includes(route().page))shell('<div class="loading"><h1>The opening library couldn’t load.</h1><p>Check your connection, then try again.</p>'+button('Try again','retry-openings','pink')+'</div>')}
}
async function loadPuzzleLibrary(){
 shell('<div class="loading"><span class="star">✦</span><h1>Bringing your puzzles to the board…</h1><p>Loading 10,000 real practice positions.</p></div>');
 try{if(!puzzleLoad)puzzleLoad=fetch('./data/puzzles.json').then(r=>{if(!r.ok)throw new Error('Puzzle library unavailable');return r.json()});data.puzzles=await puzzleLoad;indices.puzzles.clear();searchIndex.clear();for(const p of data.puzzles){indices.puzzles.set(p.id,p);searchIndex.set(p.id,[p.id,...p.themes.map(label),...p.openingTags.map(t=>t.replaceAll('_',' ')),phaseName(p.phase)].join(' ').toLowerCase())}if(['library','practice','atlas','concept','progress'].includes(route().page))render()}catch{puzzleLoad=null;if(['library','practice','atlas','concept','progress'].includes(route().page))shell('<div class="loading"><h1>The puzzle library couldn’t load.</h1><p>Check your connection, then try again.</p>'+button('Try again','retry-puzzles','pink')+'</div>')}
}
async function boot(){try{const response=await fetch('./data/manifest.json',{cache:'no-store'});if(!response.ok)throw new Error('Content manifest unavailable');data.manifest=await response.json();loaded=true;render()}catch(error){console.error('App initialization failed:',error);main.innerHTML=`<div class="loading"><h1>The app couldn’t load.</h1><p>Check your connection and try again.</p>${button('Try again','retry-load','pink')}</div>`}}
boot();

window.addEventListener('chess-account-changed',()=>{if(loaded&&!board)render();});
